package org.marketreview.nativeapp;
import android.content.Context;
import android.widget.*;
import org.json.*;
import java.util.*;
/** main is pure model. run(Context) must be invoked by the host on its UI thread/device. */
public final class ResearchCompaniesChecks {
 static int checks;static void need(boolean b,String why){checks++;if(!b)throw new AssertionError(why);}
 static void sizes(ResearchCompaniesScreen screen,Context context)throws Exception{
  float density=context.getResources().getDisplayMetrics().density;
  for(int[] size:new int[][]{{390,844},{844,390}}){int w=Math.round(size[0]*density),h=Math.round(size[1]*density);screen.setLayoutParams(new android.view.ViewGroup.LayoutParams(w,h));((Button)screen.findViewWithTag("companyListMode")).performClick();screen.measure(android.view.View.MeasureSpec.makeMeasureSpec(w,android.view.View.MeasureSpec.EXACTLY),android.view.View.MeasureSpec.makeMeasureSpec(h,android.view.View.MeasureSpec.EXACTLY));screen.layout(0,0,w,h);screen.measure(android.view.View.MeasureSpec.makeMeasureSpec(w,android.view.View.MeasureSpec.EXACTLY),android.view.View.MeasureSpec.makeMeasureSpec(h,android.view.View.MeasureSpec.EXACTLY));screen.layout(0,0,w,h);ListView list=screen.findViewWithTag("researchCompanyList");need(list.getVisibility()==android.view.View.VISIBLE&&list.getHeight()>=Math.round(80*density),"subject viewport too small "+size[0]+"x"+size[1]);list.performItemClick(null,0,0);TextView original=screen.findViewWithTag("companyOriginal");need(original.getText().toString().contains("测试公司")&&list.getVisibility()==android.view.View.GONE,"selected original internal view "+size[0]+"x"+size[1]);((Button)screen.findViewWithTag("companyGraphMode")).performClick();need(((IndustryGraph)screen.findViewWithTag("industryGraph")).getVisibility()==android.view.View.VISIBLE,"graph mode available");}
 }
 static JSONObject relation()throws Exception{return new JSONObject().put("id","r").put("topicId","t").put("documentId","d").put("stage","equipment").put("claim","生产设备").put("quote","生产设备").put("polarity","supports").put("verification","manuallyVerified").put("product","设备").put("company",new JSONObject().put("name","测试公司").put("instrumentId","SH:stock:600001").put("identityDocumentId","d").put("identityQuote","测试公司（600001，上交所）"));}
 static void model()throws Exception{
  JSONObject r=relation();Map<String,String> text=new HashMap<>();text.put("d","测试公司（600001，上交所）生产设备");ResearchCompanies.validateReferences(r,text);JSONObject wrong=new JSONObject(r.toString());wrong.getJSONObject("company").put("instrumentId","SZ:stock:600001");try{ResearchCompanies.validateReferences(wrong,text);throw new AssertionError("wrong market accepted");}catch(IllegalArgumentException expected){checks++;}text.put("d","生产设备");try{ResearchCompanies.validateReferences(r,text);throw new AssertionError("identity original removed");}catch(IllegalArgumentException expected){checks++;}
  JSONObject doc=new JSONObject().put("id","d").put("text","测试公司（600001，上交所）生产设备");String original=r.toString();JSONObject p=ResearchCompanies.project("t",new JSONArray().put(r),new JSONArray().put(doc),new JSONArray());need(p.getJSONArray("rows").length()==1,"current topic");need(p.getJSONArray("rows").getJSONObject(0).getString("verification").equals("manuallyVerified"),"manual verification retained");need(r.toString().equals(original),"input mutated");need(ResearchCompanies.project("other",new JSONArray().put(r),new JSONArray().put(doc),new JSONArray()).getJSONArray("rows").length()==0,"topic isolation");
  JSONObject old=new JSONObject().put("topicId","old").put("sequence",2).put("relations",new JSONArray().put(new JSONObject().put("id","old-r").put("company",new JSONObject().put("name","旧公司").put("stockCode","600002")).put("stage","equipment").put("status","verified").put("evidenceRefs",new JSONArray().put(new JSONObject().put("evidenceId","e").put("quote","旧引文")))));JSONObject report=new JSONObject().put("id","v2").put("legacySource","industry_research_versions").put("text",old.toString());JSONObject row=ResearchCompanies.project("legacy-topic:old",new JSONArray(),new JSONArray(),new JSONArray().put(report)).getJSONArray("rows").getJSONObject(0);need(row.getBoolean("readOnly")&&!row.getBoolean("bodyAvailable"),"archive body limitation");need(row.getString("status").equals("legacyVerified")&&row.getString("instrumentId").isEmpty(),"old status/code not promoted");
 }
 public static int run(Context c)throws Exception{
  checks=0;model();BusinessStore store=new BusinessStore(c,"research-check-"+UUID.randomUUID()+".sqlite");try{JSONObject t=store.save("topics",new JSONObject().put("name","测试主题")),d=store.save("docs",new JSONObject().put("title","公告").put("text","测试公司（600001，上交所）生产设备")),r=relation();r.remove("id");r.put("topicId",t.getString("id")).put("documentId",d.getString("id"));r.getJSONObject("company").put("identityDocumentId",d.getString("id"));JSONObject saved=store.save("relations",r);ResearchCompaniesScreen screen=new ResearchCompaniesScreen(c,store);screen.setTopic(t.getString("id"));ListView list=screen.findViewWithTag("researchCompanyList");need(list.getCount()==1,"company list");list.performItemClick(null,0,0);EditText product=screen.findViewWithTag("companyProduct"),search=screen.findViewWithTag("companySearch");product.setText("未保存产品");search.setText("公司");need(product.getText().toString().equals("未保存产品"),"filter draft");search.setText("不存在");search.setText("");list.performItemClick(null,0,0);need(product.getText().toString().equals("未保存产品"),"hidden draft");screen.reload();need(product.getText().toString().equals("未保存产品"),"reload draft");JSONObject state=screen.saveState();ResearchCompaniesScreen rebuilt=new ResearchCompaniesScreen(c,store);rebuilt.restoreState(state);need(((EditText)rebuilt.findViewWithTag("companyProduct")).getText().toString().equals("未保存产品"),"rebuild draft");need(store.read("relations").getJSONObject(0).getString("product").equals("设备"),"draft not saved to relation");JSONObject changed=new JSONObject(saved.toString()).put("claim","其他页面更改");store.save("relations",changed);screen.reload();((Button)screen.findViewWithTag("companySave")).performClick();need(((TextView)screen.findViewWithTag("companyState")).getText().toString().contains("已变化"),"stale draft rejected");((Button)screen.findViewWithTag("companyDiscard")).performClick();need(product.getText().toString().equals("设备"),"explicit discard");product.setText("设备二");((Button)screen.findViewWithTag("companySave")).performClick();need(store.read("relations").getJSONObject(0).getString("product").equals("设备二"),"company save");need(store.read("relations").getJSONObject(0).getString("verification").equals("manuallyVerified"),"manual preserved");sizes(screen,c);return checks;}finally{store.close();}
 }
 public static void main(String[] args)throws Exception{checks=0;model();System.out.println("research companies pure model: "+checks+" checks GREEN; Android native UI helper compiled, device not run");}
}
